def fold_findings(apps, schema_editor):
    """Findings were kept per check ("C3:6345", "C6:last_month", "RR-01"); review points are kept per reference
    (6345, lab, RR-01) whatever the comparison. Keep the notes on GL accounts and requests under their reference and
    start everything open; drop the rest (ratio and subtotal findings have no reference now)."""
    Finding = apps.get_model("review", "ReviewFinding")
    old = list(Finding.objects.exclude(status__in=("open", "signed_off")) | Finding.objects.filter(key__contains=":"))
    kept = {}
    for f in sorted(old, key=lambda f: f.pk):
        ref = f.key.split(":", 1)[1] if ":" in f.key else f.key
        if not (ref.startswith("RR-") or ref.isalnum()) or ref in ("gp", "np"):
            continue
        key = (f.organisation_id, f.period_end, ref)
        notes = kept.setdefault(key, [])
        if f.note.strip() and f.note.strip() not in notes:
            notes.append(f.note.strip())
    Finding.objects.filter(pk__in=[f.pk for f in old]).delete()
    for (organisation_id, period_end, ref), notes in kept.items():
        if notes:
            Finding.objects.update_or_create(organisation_id=organisation_id, period_end=period_end, key=ref,
                                             defaults={"subject": ref, "note": "\n".join(notes), "status": "open"})


